(()=>{'use strict';const n=+(document.body.dataset.chapter||1);if(n>=9)return;const query=matchMedia('(prefers-reduced-motion: reduce)'),buttons=[...document.querySelectorAll('button[id$="-play"],button[data-action="play"]')],initial=new Map(buttons.map(b=>[b,b.disabled]));let note;
function sync(){for(const b of buttons){if(query.matches){if(/^暂停/.test(b.textContent.trim()))b.click();b.disabled=true;b.setAttribute('aria-describedby','motion-preference-note');}else{b.disabled=initial.get(b);b.removeAttribute('aria-describedby');}}if(query.matches&&buttons.length){if(!note){note=document.createElement('p');note.id='motion-preference-note';note.className='motion-hint';note.textContent='已按系统“减弱动态”设置暂停连续播放；时间与参数滑块仍可逐步操作。';buttons[0].parentElement.append(note);}note.hidden=false;}else if(note)note.hidden=true;}
if(document.querySelector('[data-action="play"]'))new IntersectionObserver(es=>es.forEach(e=>{if(!e.isIntersecting)buttons.forEach(b=>{if(/^暂停/.test(b.textContent.trim()))b.click();});})).observe(document.querySelector('.g-product'));query.addEventListener('change',sync);document.addEventListener('visibilitychange',()=>{if(document.hidden)buttons.forEach(b=>{if(/^暂停/.test(b.textContent.trim()))b.click();});});sync();
})();
